function solve(graph) {
    const n = graph.length;
    const color = new Array(n).fill(-1);
    for (let s = 0; s < n; s++) {
        if (color[s] !== -1) continue;
        color[s] = 0;
        const queue = [s];
        for (let head = 0; head < queue.length; head++) {
            const u = queue[head];
            for (const v of graph[u]) {
                if (color[v] === -1) {
                    color[v] = 1 - color[u];
                    queue.push(v);
                } else if (color[v] === color[u]) {
                    return false;
                }
            }
        }
    }
    return true;
}

