function solve(program) {
    const logs = [];
    const microtasks = [];
    const timers = [];
    let now = 0;
    let seq = 0;
    const run = (statements) => {
        for (const st of statements) {
            if (st[0] === 'log') {
                logs.push(st[1]);
            } else if (st[0] === 'timeout') {
                timers.push({ due: now + st[1], seq: seq++, body: st[2] });
            } else if (st[0] === 'microtask') {
                microtasks.push(st[1]);
            }
        }
    };
    const drain = () => {
        while (microtasks.length > 0) run(microtasks.shift());
    };
    run(program);
    drain();
    while (timers.length > 0) {
        let best = 0;
        for (let i = 1; i < timers.length; i++) {
            const t = timers[i];
            const b = timers[best];
            if (t.due < b.due || (t.due === b.due && t.seq < b.seq)) best = i;
        }
        const timer = timers.splice(best, 1)[0];
        now = timer.due;
        run(timer.body);
        drain();
    }
    return logs;
}

