function solve(limit, tasks) {
    const n = tasks.length;
    const result = tasks.map(() => [-1, -1]);
    const started = new Array(n).fill(false);
    const finished = new Array(n).fill(false);
    let running = [];
    let time = 0;
    while (true) {
        let changed = true;
        while (changed) {
            changed = false;
            const still = [];
            for (const r of running) {
                if (r.end <= time) {
                    finished[r.index] = true;
                    changed = true;
                } else {
                    still.push(r);
                }
            }
            running = still;
            while (running.length < limit) {
                let pick = -1;
                for (let i = 0; i < n; i++) {
                    if (!started[i] && tasks[i][1].every((d) => finished[d])) {
                        pick = i;
                        break;
                    }
                }
                if (pick === -1) break;
                started[pick] = true;
                result[pick] = [time, time + tasks[pick][0]];
                running.push({ index: pick, end: time + tasks[pick][0] });
                changed = true;
            }
        }
        if (running.length === 0) break;
        time = Math.min(...running.map((r) => r.end));
    }
    return result;
}

