function solve(cells, updates) {
    const defs = new Map(Object.entries(cells));
    const evaluate = () => {
        const values = new Map();
        const state = new Map();
        const calc = (name) => {
            if (values.has(name)) return values.get(name);
            if (!defs.has(name)) return null;
            if (state.get(name) === 'visiting') return null;
            state.set(name, 'visiting');
            const def = defs.get(name);
            let result;
            if (typeof def === 'number') {
                result = def;
            } else {
                const op = def[0];
                const nums = [];
                let ok = true;
                for (const arg of def.slice(1)) {
                    const v = typeof arg === 'number' ? arg : calc(arg);
                    if (v === null) {
                        ok = false;
                        break;
                    }
                    nums.push(v);
                }
                if (!ok) result = null;
                else if (op === 'sum') result = nums.reduce((a, b) => a + b, 0);
                else if (op === 'product') result = nums.reduce((a, b) => a * b, 1);
                else if (op === 'max') result = Math.max(...nums);
                else result = Math.min(...nums);
            }
            values.set(name, result);
            state.set(name, 'done');
            return result;
        };
        for (const name of defs.keys()) calc(name);
        return values;
    };
    let prev = evaluate();
    const out = [];
    for (const [name, def] of updates) {
        defs.set(name, def);
        const cur = evaluate();
        const changed = [];
        for (const [n, v] of cur) {
            if (!prev.has(n) || prev.get(n) !== v) changed.push(n);
        }
        changed.sort();
        out.push(changed);
        prev = cur;
    }
    return out;
}

